@startuml

class OOBank {}

class Branch {
  + address : string
  + branchNumber : int
}

class Division {}

class Subdivision {}

class Employee {}

class Customer {}

class Account {
  + accountNumber : int
  + balance : double
  + interestRate : float
  + monthlyFee : float
}

class MortgageAccount extends Account {
  + property : string
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate : date
}

class SecondaryCard {}

class Privilege {}

class Manager {}

class PersonalBanker {}

OOBank "1" *-- "*" Division
OOBank "1" *-- "*" Branch
Division "1" *-- "*" Subdivision
Division "1" -- "1" Manager
Division "1" -- "*" Employee
Subdivision "1" -- "1" Branch
Branch "1" -- "*" Account
Branch "1" -- "*" Customer
Customer "1" -- "0..*" Account
Customer "1" -- "0..*" Account : joint
Account "1" -- "*" Privilege
CreditCardAccount "1" -- "*" SecondaryCard
Customer "*" -- "0..1" Employee : personal banker

@enduml

